// Projection file names (C-event-log §8).
const (
	DecisionsDir = "decisions"
	RegistryFile = "registry.yaml"
	StateFile    = "state.json"
)

// Committed and local projections (C-event-log v5 §8, D-projections-in-git):
// per-item files are committed; the aggregates are git-ignored and
// regenerated by every write and by `ekumen project`.
var LocalProjections = []string{RegistryFile, StateFile}

// ErrNoEvents is returned by WriteProjections for an empty log: projecting
// it would replace hand-written records with empty ones.
var ErrNoEvents = fmt.Errorf("the event log is empty; projections left as they are")

// WriteProjections regenerates decisions/<id>.yaml for every decision,
// registry.yaml and state.json from the snapshot, and returns the paths
// (relative to the project root) whose content changed. Files are written
// atomically. Decision files for ids not in the log are left alone.
func (s *Snapshot) WriteProjections() ([]string, error) {
	if len(s.Events) == 0 {
		return nil, ErrNoEvents
	}
	files := map[string][]byte{}
	for _, id := range s.DecisionIDs() {
		b, err := s.DecisionYAML(id)
		if err != nil {
			return nil, err
		}
		files[filepath.Join(DecisionsDir, id+".yaml")] = b
	}
	reg, err := s.RegistryYAML()
	if err != nil {
		return nil, err
	}
	files[RegistryFile] = reg
	st, err := s.StateJSON()
	if err != nil {
		return nil, err
	}
	files[StateFile] = st

	var changed []string
	for _, name := range sortedKeys(files) {
		p := filepath.Join(s.EkumenDir(), name)
		if old, err := os.ReadFile(p); err == nil && bytes.Equal(old, files[name]) {
			continue
		}
		if err := writeAtomic(p, files[name]); err != nil {
			return changed, err
		}
		changed = append(changed, s.rel(p))
	}
	return changed, nil
}

func writeAtomic(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	f, err := os.CreateTemp(filepath.Dir(path), ".tmp-projection-")
	if err != nil {
		return err
	}
	tmp := f.Name()
	if _, err := f.Write(data); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Chmod(tmp, 0o644); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		os.Remove(tmp)
		return err
	}
	return nil
}

// ---- YAML nodes ----

func str(v string) *yaml.Node {
	n := &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: v}
	switch strings.ToLower(v) {
	case "y", "n", "yes", "no", "on", "off":
		n.Style = yaml.DoubleQuotedStyle // YAML 1.1 readers would see a bool
	}
	return n
}

// date writes a YYYY-MM-DD string plain, as the hand-written records do.
func date(v string) *yaml.Node {
	if _, err := time.Parse(time.DateOnly, v); err == nil {
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!timestamp", Value: v}
	}
	return str(v)
}

func null() *yaml.Node { return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"} }

func intNode(i int) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.Itoa(i)}
}

func boolNode(b bool) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: strconv.FormatBool(b)}
}

func optStr(p *string, asDate bool) *yaml.Node {
	if p == nil {
		return null()
	}
	if asDate {
		return date(*p)
	}
	return str(*p)
}

func seq(flow bool, items ...*yaml.Node) *yaml.Node {
	n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Content: items}
	if flow {
		n.Style = yaml.FlowStyle
	}
	return n
}

func strs(v []string) *yaml.Node {
	items := make([]*yaml.Node, len(v))
	for i, s := range v {
		items[i] = str(s)
	}
	return seq(true, items...)
}

type kv struct {
	k string
	v *yaml.Node
}

func mapping(flow bool, pairs ...kv) *yaml.Node {
	n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	if flow {
		n.Style = yaml.FlowStyle
	}
	for _, p := range pairs {
		n.Content = append(n.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: p.k}, p.v)
	}
	return n
}

func encodeYAML(header string, n *yaml.Node) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString(header)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(n); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

const generatedHeader = "# Generated by `ekumen` from .ekumen/events. Do not edit; run `ekumen project` to regenerate.\n"

// DecisionYAML renders decisions/<id>.yaml (C-decision-record §4): every
// §1 field, then the lifecycle fields in the order listed there. Unset
// lifecycle fields are left out, as in the hand-written records; questions
// is always present.
func (s *Snapshot) DecisionYAML(id string) ([]byte, error) {
	d := s.DecisionView(id)
	options := make([]*yaml.Node, len(d.Options))
	for i, o := range d.Options {
		options[i] = mapping(true, kv{"id", str(o.ID)}, kv{"tradeoff", str(o.Tradeoff)})
	}
	pairs := []kv{{"id", str(d.ID)}}
	if len(d.Aliases) > 0 {
		pairs = append(pairs, kv{"aliases", strs(d.Aliases)})
	}
	pairs = append(pairs,
		kv{"title", str(d.Title)},
		kv{"tier", intNode(d.Tier)},
		kv{"raised_by", mapping(true, kv{"task", optStr(d.RaisedBy.Task, false)}, kv{"session", str(d.RaisedBy.Session)}, kv{"on", date(d.RaisedBy.On)})},
		kv{"question", str(d.Question)},
		kv{"options", seq(false, options...)},
		kv{"recommendation", optStr(d.Recommendation, false)},
		kv{"default_if_no_answer", optStr(d.DefaultIfNoAnswer, false)},
		kv{"deadline", optStr(d.Deadline, true)},
		kv{"blocks", strs(d.Blocks)},
		kv{"contract_impact", strs(d.ContractImpact)},
	)
	ctx := []kv{{"summary", str(d.Context.Summary)}}
	if len(d.Context.Evidence) > 0 {
		ctx = append(ctx, kv{"evidence", strs(d.Context.Evidence)})
	}
	if len(d.Context.PriorDecisions) > 0 {
		ctx = append(ctx, kv{"prior_decisions", strs(d.Context.PriorDecisions)})
	}
	pairs = append(pairs, kv{"context", mapping(false, ctx...)}, kv{"status", str(d.Status)})
	qs := make([]*yaml.Node, len(d.Questions))
	for i, q := range d.Questions {
		qs[i] = mapping(false, kv{"id", str(q.ID)}, kv{"at", str(q.At)}, kv{"by", str(q.By)}, kv{"to", str(q.To)},
			kv{"text", str(q.Text)}, kv{"answer", optStr(q.Answer, false)}, kv{"answered_by", optStr(q.AnsweredBy, false)},
			kv{"answered_at", optStr(q.AnsweredAt, false)})
	}
	pairs = append(pairs, kv{"questions", seq(len(qs) == 0, qs...)})
	opt := func(k string, p *string, asDate bool) {
		if p != nil {
			pairs = append(pairs, kv{k, optStr(p, asDate)})
		}
	}
	opt("answer", d.Answer, false)
	opt("answer_note", d.AnswerNote, false)
	opt("decided_by", d.DecidedBy, false)
	opt("decided_on", d.DecidedOn, true)
	opt("superseded_by", d.SupersededBy, false)
	opt("applied_on", d.AppliedOn, true)
	if d.Applied != nil {
		pairs = append(pairs, kv{"applied", mapping(true, kv{"amended_tasks", strs(d.Applied.AmendedTasks)},
			kv{"unblocked_tasks", strs(d.Applied.UnblockedTasks)}, kv{"notified_sessions", strs(d.Applied.NotifiedSessions)})})
	}
	return encodeYAML(generatedHeader, mapping(false, pairs...))
}

// ConfigFile is an optional, committed, owner-edited .ekumen/config.yaml.
// Its `project` field names the project.
const ConfigFile = "config.yaml"

// ProjectName is the project's name, in this order:
//  1. `project:` in .ekumen/config.yaml, if the file exists (committed);
//  2. Options.Name: the CLI passes the origin remote's repository name,
//     but only when the project root is the repository's top, so a project
//     in a monorepo subfolder is not named after the whole repository;
//  3. the name of the folder holding .ekumen/.
//
// registry.yaml is not read: it is a local projection (D-projections-in-git).
func (s *Snapshot) ProjectName() string {
	if v := s.yamlField(ConfigFile, "project"); v != "" {
		return v
	}
	if s.name != "" {
		return s.name
	}
	return filepath.Base(s.Root)
}

// Lead is the lead's handle: the latest lead actor in the log, else the
// `lead` field of an existing registry.yaml.
func (s *Snapshot) Lead() string {
	for i := len(s.Events) - 1; i >= 0; i-- {
		if s.Events[i].Actor.Role == event.RoleLead {
			return s.Events[i].Actor.ID
		}
	}
	return s.yamlField(RegistryFile, "lead")
}

// yamlField reads a top-level string field of a YAML file in .ekumen/.
func (s *Snapshot) yamlField(file, key string) string {
	b, err := os.ReadFile(filepath.Join(s.EkumenDir(), file))
	if err != nil {
		return ""
	}
	var m map[string]any
	if yaml.Unmarshal(b, &m) != nil {
		return ""
	}
	v, _ := m[key].(string)
	return v
}

// RegistryYAML renders registry.yaml in the shape of the hand-written one:
// project, lead, tasks by id, external, contracts. Task status is derived
// from events plus the observations made at load time.
func (s *Snapshot) RegistryYAML() ([]byte, error) {
	tasks := mapping(false)
	for _, id := range s.TaskIDs() {
		t := s.TaskView(id)
		raw := s.State.Tasks[id]
		pairs := []kv{{"title", str(t.Title)}}
		if len(t.Aliases) > 0 {
			pairs = append(pairs, kv{"aliases", strs(t.Aliases)})
		}
		pairs = append(pairs,
			kv{"kind", str(t.Kind)},
			kv{"brief", optStr(ptr(raw.Brief), false)}, // as recorded, relative to .ekumen/
			kv{"approved", optStr(t.ApprovedOn, true)},
			kv{"blocked_by", strs(t.BlockedBy)},
			kv{"repo", optStr(ptr(raw.Repo), false)},
			kv{"base_branch", optStr(ptr(raw.BaseBranch), false)},
			kv{"branch", optStr(t.Branch, false)},
			kv{"worktree", optStr(ptr(raw.Worktree), false)},
			kv{"session", optStr(t.Session, false)},
			kv{"tier_grants", strs(t.TierGrants)},
			kv{"status", str(t.Status)},
		)
		tasks.Content = append(tasks.Content, str(id), mapping(false, pairs...))
	}
	externals := mapping(false)
	for _, x := range s.ExternalViews() {
		externals.Content = append(externals.Content, str(x.ID), mapping(true,
			kv{"what", str(x.What)}, kv{"owner_team", str(x.OwnerTeam)}, kv{"asked_on", date(x.AskedOn)},
			kv{"needed_by", date(x.NeededBy)}, kv{"blocks", strs(x.Blocks)}, kv{"resolved", boolNode(x.Resolved)}))
	}
	if len(externals.Content) == 0 {
		externals.Style = yaml.FlowStyle
	}
	contracts := mapping(false)
	for _, c := range s.ContractViews() {
		pairs := []kv{{"title", str(c.Title)}}
		if len(c.Aliases) > 0 {
			pairs = append(pairs, kv{"aliases", strs(c.Aliases)})
		}
		pairs = append(pairs, kv{"path", optStr(c.Path, false)}, kv{"status", str(c.Status)}, kv{"version", intNode(c.Version)})
		contracts.Content = append(contracts.Content, str(c.ID), mapping(true, pairs...))
	}
	if len(contracts.Content) == 0 {
		contracts.Style = yaml.FlowStyle
	}
	if len(tasks.Content) == 0 {
		tasks.Style = yaml.FlowStyle
	}
	lead := null()
	if l := s.Lead(); l != "" {
		lead = str(l)
	}
	root := mapping(false,
		kv{"project", str(s.ProjectName())},
		kv{"lead", lead},
		kv{"tasks", tasks},
		kv{"external", externals},
		kv{"contracts", contracts},
	)
	return encodeYAML(generatedHeader+"# Task status is derived from events plus pull requests observed when this file was written.\n", root)
}

// StateDoc is the shape of state.json.
type StateDoc struct {
	Generated string      `json:"generated"`
	AsOf      string      `json:"as_of"`
	LastEvent string      `json:"last_event"`
	Project   string      `json:"project"`
	Tasks     []Task      `json:"tasks"`
	Decisions []Decision  `json:"decisions"`
	Contracts []Contract  `json:"contracts"`
	Externals []External  `json:"externals"`
	Questions []Question  `json:"questions"`
	Inbox     StateInbox  `json:"inbox"`
	Conflicts []Conflict  `json:"conflicts"`
	Counts    StateCounts `json:"counts"`
}

// StateInbox holds the lead's and orchestrator's inboxes.
type StateInbox struct {
	Lead         []InboxItem `json:"lead"`
	Orchestrator []InboxItem `json:"orchestrator"`
}

// StateCounts are summary counts.
type StateCounts struct {
	TasksByStatus map[string]int `json:"tasks_by_status"`
	DecisionsOpen int            `json:"decisions_open"`
	RoutesOpen    int            `json:"routes_open"`
	Conflicts     int            `json:"conflicts"`
}

// Counts computes the status counts.
func (s *Snapshot) Counts() StateCounts {
	c := StateCounts{TasksByStatus: map[string]int{}}
	for _, id := range s.TaskIDs() {
		c.TasksByStatus[string(s.TaskStatus(id))]++
	}
	for _, id := range s.DecisionIDs() {
		if s.State.Decisions[id].Status == "pending" {
			c.DecisionsOpen++
		}
	}
	c.RoutesOpen = s.OpenRoutes()
	c.Conflicts = len(s.Conflicts())
	return c
}

// StateJSON renders state.json: everything the CLI derives, as of the
// snapshot's UTC date. Observed PR details are left out (C-event-log §7
// rule 2); task status includes them.
func (s *Snapshot) StateJSON() ([]byte, error) {
	tasks := s.Tasks("")
	for i := range tasks {
		tasks[i].Observed = nil
	}
	doc := StateDoc{
		Generated: "by `ekumen` from .ekumen/events; do not edit",
		AsOf:      s.Now.Format(time.DateOnly),
		Project:   s.ProjectName(),
		Tasks:     tasks, Decisions: s.Decisions(""), Contracts: s.ContractViews(), Externals: s.ExternalViews(),
		Questions: s.Questions(),
		Inbox:     StateInbox{Lead: s.Inbox(string(event.RoleLead)), Orchestrator: s.Inbox(string(event.RoleOrchestrator))},
		Conflicts: s.ConflictViews(), Counts: s.Counts(),
	}
	if n := len(s.Events); n > 0 {
		doc.LastEvent = s.Events[n-1].ID
	}
	b, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

// CheckProjections compares the committed per-item projections
// (decisions/<id>.yaml) with what the events give (`ekumen project
// --check`, D-projections-in-git). It reports, by path relative to the
// project root, each file that is stale, missing, or names a decision the
// log does not have. The aggregates (registry.yaml, state.json) are local
// and not checked.
func (s *Snapshot) CheckProjections() ([]Invalid, error) {
	out := []Invalid{}
	want := map[string]bool{}
	for _, id := range s.DecisionIDs() {
		name := id + ".yaml"
		want[name] = true
		b, err := s.DecisionYAML(id)
		if err != nil {
			return nil, err
		}
		p := filepath.Join(s.EkumenDir(), DecisionsDir, name)
		old, err := os.ReadFile(p)
		switch {
		case errors.Is(err, os.ErrNotExist):
			out = append(out, Invalid{Path: s.rel(p), Error: "missing: run `ekumen project` and commit it"})
		case err != nil:
			out = append(out, Invalid{Path: s.rel(p), Error: err.Error()})
		case !bytes.Equal(old, b):
			out = append(out, Invalid{Path: s.rel(p), Error: "does not match the events: run `ekumen project` and commit it"})
		}
	}
	ents, err := os.ReadDir(filepath.Join(s.EkumenDir(), DecisionsDir))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	for _, e := range ents {
		if e.IsDir() || filepath.Ext(e.Name()) != ".yaml" || want[e.Name()] {
			continue
		}
		out = append(out, Invalid{Path: s.rel(filepath.Join(s.EkumenDir(), DecisionsDir, e.Name())),
			Error: "no decision with this id in the event log"})
	}
	return out, nil
}
